<template>
  <main class="multi-lan">
    <div class="demo-strip"><span>产品设计预览 · 示例数据</span><label>场景 <select v-model="scenario" @change="reset"><option value="normal">多个局域网</option><option value="no-default">只有 lan1 / lan2</option><option value="partial">lan1 策略服务异常</option></select></label></div>
    <div class="breadcrumb">首页 <span>›</span> 局域网设备管理</div>
    <header class="heading"><div><h1>局域网设备管理</h1><p>查看所有网络中的设备，按局域网管理地址与上网策略。</p></div><span class="live"><i></i> {{ networks.length }} 个局域网</span></header>
    <div class="workspace">
      <aside class="network-nav" aria-label="选择局域网">
        <span class="eyebrow">网络范围</span>
        <button :class="{ selected: selected === 'all' }" @click="choose('all')"><span class="network-icon">◎</span><span><strong>全部局域网</strong><small>跨网络查看设备</small></span><b>{{ knownDevices.length }}</b></button>
        <button v-for="network in networks" :key="network.id" :class="{ selected: selected === network.id }" @click="choose(network.id)"><span class="network-icon">⌘</span><span><strong>{{ network.name }} <em>{{ network.id }}</em></strong><small>{{ network.subnet }}</small></span><b>{{ count(network.id) }}</b></button>
        <button :class="{ selected: selected === 'unknown' }" @click="choose('unknown')"><span class="network-icon">?</span><span><strong>待确认归属</strong><small>仅展示，暂不可配置</small></span><b>1</b></button>
        <p class="nav-note">网络来自现有接口配置。新增网络与 VLAN 请在系统网络设置中完成。</p>
      </aside>
      <section class="main-panel">
        <header class="scope-heading"><div><span class="eyebrow">{{ selected === 'all' ? '网络总览' : '当前网络' }}</span><h2>{{ current?.name || (selected === 'unknown' ? '待确认归属' : '全部局域网') }} <span v-if="current">{{ current.id }}</span></h2><p>{{ current ? `${current.subnet} · ${current.device} · ${current.zone} 区域` : selected === 'unknown' ? '已发现设备，但证据不足以确定所在网络。' : '设备按所在网络分别展示，策略在各自网络内生效。' }}</p></div><span class="status" :class="current && engineReady(current.id) ? 'good' : ''">{{ current ? engineReady(current.id) ? '策略服务可用' : '策略服务未就绪' : `${visibleDevices.filter(d => d.online).length} 台在线` }}</span></header>
        <div v-if="selected === 'all'" class="network-cards"><button v-for="network in networks" :key="network.id" @click="choose(network.id)"><div><strong>{{ network.name }}</strong><span>{{ network.id }}</span></div><p>{{ network.subnet }}</p><footer><span>{{ count(network.id) }} 台设备</span><small :class="engineReady(network.id) ? 'good-text' : 'warn-text'">{{ engineReady(network.id) ? '策略可用' : '仅查看' }}</small></footer></button></div>
        <p v-if="selected === 'unknown'" class="notice">设备来自租约或历史记录。确定接口归属后才开放限速、地址保留和上网路线设置。</p>
        <p v-if="current && !engineReady(current.id)" class="notice">{{ scenario === 'partial' && current.id === 'lan1' ? '此网络的策略服务异常。设备浏览仍可用，其他网络不受影响。' : '此网络尚未接入策略服务，可查看设备，暂不能设置限速和配额。' }}</p>
        <nav class="tabs" aria-label="工作区"><button v-for="item in tabs" :key="item.id" :class="{ active: tab === item.id }" @click="tab = item.id; search = ''; feedback = ''">{{ item.label }}</button></nav>
        <template v-if="tab === 'devices'">
          <div class="toolbar"><div class="filters"><button :class="{ active: !onlineOnly }" @click="onlineOnly = false">全部 {{ visibleDevices.length }}</button><button :class="{ active: onlineOnly }" @click="onlineOnly = true">在线 {{ visibleDevices.filter(d => d.online).length }}</button></div><input v-model="search" aria-label="搜索设备" placeholder="搜索名称、IP 或 MAC" /></div>
          <div class="table-scroll"><table><thead><tr><th>设备</th><th>所在网络</th><th>当前地址</th><th>实时流量 ↓ / ↑</th><th>上网策略</th><th></th></tr></thead><tbody><tr v-for="device in filteredDevices" :key="`${device.network}:${device.mac}`" @click="opened = device"><td><div class="device-name"><span class="device-icon">{{ device.icon }}</span><div><strong>{{ device.name }}</strong><small><i :class="{ online: device.online }"></i>{{ device.online ? '在线' : '离线' }} · {{ device.connection }}</small></div></div></td><td><button class="network-link" @click.stop="choose(device.network)">{{ networkName(device.network) }} <small>{{ device.network === 'unknown' ? '待确认' : device.network }}</small></button></td><td><span class="mono">{{ device.ip }}</span><small class="mac mono">{{ device.mac }}</small></td><td><span v-if="device.online && engineReady(device.network)">{{ device.flow }} <small>MB/s</small></span><span v-else class="muted">{{ device.online ? '暂无数据' : '—' }}</span></td><td><span class="policy" :class="{ limited: device.policy.includes('限速') }">{{ device.policy }}</span></td><td><button class="text-button" @click.stop="opened = device">详情 ›</button></td></tr><tr v-if="!filteredDevices.length"><td colspan="6" class="empty">没有符合条件的设备</td></tr></tbody></table></div>
          <p class="table-note">{{ selected === 'all' ? '同一 MAC 出现在不同网络时分别列出；未知归属设备单独保留。' : '当前列表和设备操作均限定在所选网络。' }}</p>
        </template>
        <template v-else-if="!current">
          <div class="scope-empty"><span>⌘</span><h3>选择一个局域网，{{ tab === 'settings' ? '管理网络设置' : '管理分组与计划' }}</h3><p>每个网络拥有独立的 DHCP、上网路线和设备分组。</p><div><button v-for="network in networks" :key="network.id" @click="choose(network.id)">{{ network.name }} · {{ network.id }} ›</button></div></div>
        </template>
        <template v-else-if="tab === 'settings'">
          <article class="authority"><div><strong>{{ current.localDhcp ? '本机分配地址' : '由外部 DHCP 分配地址' }}</strong><p>{{ current.localDhcp ? `以下设置仅作用于 ${current.name}（${current.id}）。` : '请在分配地址的主路由修改 DHCP 与上网路线。此处保留只读信息。' }}</p></div><span class="status" :class="{ good: current.localDhcp }">{{ current.localDhcp ? '允许编辑' : '只读' }}</span></article>
          <div class="settings-grid"><article class="setting"><h3>地址分配 DHCP</h3><p>为 {{ current.name }} 的设备分配 IPv4 地址。</p><label>地址池起点<input v-model="poolStart" :disabled="!current.localDhcp" /></label><label>地址池终点<input v-model="poolEnd" :disabled="!current.localDhcp" /></label><label>租约时间<select v-model="lease" :disabled="!current.localDhcp"><option>12 小时</option><option>24 小时</option></select></label><button class="primary" :disabled="!current.localDhcp" @click="prepareDhcp">预览修改</button></article><article class="setting"><h3>上网路线</h3><p>网关选项属于当前网络，不跨网络复用。</p><div class="route-info"><strong>默认路线</strong><span>{{ current.gateway }}</span><small>{{ current.localDhcp ? '通过本机上网' : '外部主路由' }}</small></div><h3>流量与设备策略</h3><p>限速与配额 {{ engineReady(current.id) ? '可用' : '暂不可用' }} · {{ current.id }}</p><small class="muted">跨网互访和 VLAN 隔离由系统防火墙管理。</small></article></div>
        </template>
        <template v-else>
          <article class="authority"><div><strong>{{ current.name }} 的分组与计划</strong><p>分组成员和上网路线均来自 {{ current.id }}，迁移到其他网络后需重新确认策略。</p></div><span class="status">网络内生效</span></article><div class="group-card"><span class="network-icon">▦</span><div><h3>{{ current.id === 'lan1' ? '办公设备' : current.id === 'lan2' ? '访客设备' : '家庭设备' }}</h3><p>{{ count(current.id) }} 台设备 · {{ engineReady(current.id) ? '可设置网络内计划' : '等待策略服务接入' }}</p></div><button @click="tab = 'devices'">查看成员 ›</button></div>
        </template>
        <p v-if="feedback" class="feedback" role="status">{{ feedback }}</p>
      </section>
    </div>
    <div v-if="opened" class="overlay" @click.self="opened = undefined"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="device-title" tabindex="-1" ref="dialogRoot"><header><span>设备详情</span><button aria-label="关闭详情" @click="opened = undefined">×</button></header><div class="drawer-title"><span class="device-icon">{{ opened.icon }}</span><h2 id="device-title">{{ opened.name }}</h2><p>{{ networkName(opened.network) }} · {{ opened.network }}</p></div><dl><dt>所属网络</dt><dd>{{ networkName(opened.network) }}（{{ opened.network }}）</dd><dt>当前地址</dt><dd>{{ opened.ip }}</dd><dt>MAC 地址</dt><dd class="mono">{{ opened.mac }}</dd><dt>策略范围</dt><dd>仅当前网络</dd></dl><p class="notice">{{ opened.network === 'unknown' ? '归属未确认，暂不能配置网络策略。' : !engineReady(opened.network) ? '此网络的策略服务未就绪，暂不能配置限速。' : '设备转入其他网络后，不自动继承此网络的限速与配额。' }}</p><label class="rate-label">下载限速 <select v-model="rate" :disabled="!engineReady(opened.network)"><option value="20">20 Mbps</option><option value="50">50 Mbps</option><option value="100">100 Mbps</option></select></label><button class="primary" :disabled="!engineReady(opened.network) || !opened.online" @click="prepareRate">预览限速设置</button><small v-if="!opened.online" class="offline-note">设备离线，恢复在线并确认归属后可设置。</small></section></div>
    <div v-if="plan" class="overlay plan-overlay" @click.self="plan = undefined"><section class="plan" role="dialog" aria-modal="true" aria-labelledby="plan-title" tabindex="-1" ref="planRoot"><span class="eyebrow">变更预览 · 示例</span><h2 id="plan-title">{{ plan.title }}</h2><dl><dt>目标网络</dt><dd>{{ networkName(plan.network) }}（{{ plan.network }}）</dd><dt>修改内容</dt><dd>{{ plan.change }}</dd><dt>配置影响</dt><dd>{{ plan.impact }}</dd></dl><p v-if="plan.kind === 'dhcp'" class="notice">DHCP 服务由多个网络共用；应用时可能短暂影响同一服务实例下的其他网络。其他网络的配置保持原值。</p><p>这是交互演示，确认后只更新本页示例状态。</p><footer><button @click="plan = undefined">取消</button><button class="primary" @click="applyPlan">确认应用（演示）</button></footer></section></div>
  </main>
</template>

<script setup lang="ts">
import { computed, nextTick, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
type Network = { id: string; name: string; subnet: string; device: string; zone: string; gateway: string; localDhcp: boolean }
type Device = { network: string; name: string; ip: string; mac: string; online: boolean; connection: string; icon: string; flow: string; policy: string }
type Plan = { kind: 'rate' | 'dhcp'; network: string; title: string; change: string; impact: string; device?: Device; rate?: string }
const route = useRoute(), router = useRouter()
const scenario = ref('normal'), selected = ref(String(route.query.network || 'all')), tab = ref('devices')
const tabs = [{ id: 'devices', label: '设备' }, { id: 'groups', label: '分组与计划' }, { id: 'settings', label: '局域网设置' }]
const search = ref(''), onlineOnly = ref(false), opened = ref<Device>(), plan = ref<Plan>(), feedback = ref(''), rate = ref('50')
const dialogRoot = ref<HTMLElement>(), planRoot = ref<HTMLElement>()
watch(opened, async value => { if (value) { await nextTick(); dialogRoot.value?.focus() } })
watch(plan, async value => { if (value) { await nextTick(); planRoot.value?.focus() } })
function keydown(event: KeyboardEvent) {
  if (event.key === 'Escape') { if (plan.value) plan.value = undefined; else opened.value = undefined }
  if (event.key !== 'Tab') return
  const root = plan.value ? planRoot.value : opened.value ? dialogRoot.value : undefined
  if (!root) return
  const elements = Array.from(root.querySelectorAll<HTMLElement>('button:not(:disabled), select:not(:disabled), input:not(:disabled)'))
  const first = elements[0], last = elements[elements.length - 1]
  if (event.shiftKey && (document.activeElement === first || document.activeElement === root)) { event.preventDefault(); last?.focus() }
  else if (!event.shiftKey && (document.activeElement === last || document.activeElement === root)) { event.preventDefault(); first?.focus() }
}
document.addEventListener('keydown', keydown)
onUnmounted(() => document.removeEventListener('keydown', keydown))
const networks = computed<Network[]>(() => [
  { id: 'lan', name: '家庭网络', subnet: '192.168.1.0/24', device: 'br-lan', zone: 'home', gateway: '192.168.1.1', localDhcp: true },
  { id: 'lan1', name: '办公网络', subnet: '192.168.10.0/24', device: 'br-office', zone: 'office', gateway: '192.168.10.1', localDhcp: true },
  { id: 'lan2', name: '访客网络', subnet: '192.168.20.0/24', device: 'br-guest', zone: 'guest', gateway: '192.168.20.254', localDhcp: false },
].filter(n => scenario.value !== 'no-default' || n.id !== 'lan'))
const devices = ref<Device[]>([
  { network: 'lan', name: '客厅电视', ip: '192.168.1.101', mac: '02:00:00:00:01:01', online: true, connection: '有线', icon: '▣', flow: '2.40 / 0.08', policy: '默认上网' },
  { network: 'lan', name: '家庭 NAS', ip: '192.168.1.110', mac: '02:00:00:00:01:02', online: true, connection: '有线', icon: '▤', flow: '8.20 / 1.34', policy: '地址保留' },
  { network: 'lan', name: '平板电脑', ip: '192.168.1.122', mac: '02:00:00:00:01:03', online: false, connection: 'Wi-Fi', icon: '▯', flow: '—', policy: '默认上网' },
  { network: 'lan1', name: '设计工作站', ip: '192.168.10.100', mac: '02:00:00:00:02:01', online: true, connection: '有线', icon: '▱', flow: '4.10 / 0.62', policy: '限速 100 Mbps' },
  { network: 'lan1', name: '会议室打印机', ip: '192.168.10.120', mac: '02:00:00:00:02:02', online: true, connection: 'Wi-Fi', icon: '▥', flow: '0.01 / 0.01', policy: '地址保留' },
  { network: 'lan2', name: '访客手机', ip: '192.168.20.105', mac: '02:00:00:00:03:01', online: true, connection: 'Wi-Fi', icon: '▯', flow: '—', policy: '默认上网' },
  { network: 'lan2', name: '访客笔记本', ip: '192.168.20.109', mac: '02:00:00:00:02:01', online: true, connection: 'Wi-Fi', icon: '▱', flow: '—', policy: '默认上网' },
  { network: 'unknown', name: '历史设备', ip: '—', mac: '02:00:00:00:04:01', online: false, connection: '未知', icon: '?', flow: '—', policy: '归属待确认' },
])
const knownDevices = computed(() => devices.value.filter(d => networks.value.some(n => n.id === d.network)))
const current = computed(() => networks.value.find(n => n.id === selected.value))
const visibleDevices = computed(() => selected.value === 'all' ? knownDevices.value : devices.value.filter(d => d.network === selected.value))
const filteredDevices = computed(() => visibleDevices.value.filter(d => (!onlineOnly.value || d.online) && `${d.name} ${d.ip} ${d.mac}`.toLowerCase().includes(search.value.toLowerCase())))
const count = (id: string) => devices.value.filter(d => d.network === id).length
const networkName = (id: string) => networks.value.find(n => n.id === id)?.name || '待确认归属'
const engineReady = (id: string) => networks.value.some(n => n.id === id) && (id === 'lan' || (id === 'lan1' && scenario.value !== 'partial'))
const poolStart = ref(''), poolEnd = ref(''), lease = ref('12 小时')
const savedDhcp = new Map<string, { start: string; end: string; lease: string }>()
watch(current, n => { const saved = n && savedDhcp.get(n.id); const prefix = n?.gateway.split('.').slice(0, 3).join('.') || ''; poolStart.value = saved?.start || `${prefix}.100`; poolEnd.value = saved?.end || `${prefix}.200`; lease.value = saved?.lease || '12 小时' }, { immediate: true })
function choose(id: string) { selected.value = id; opened.value = undefined; plan.value = undefined; search.value = ''; onlineOnly.value = false; feedback.value = ''; void router.replace({ query: { ...route.query, network: id } }) }
watch(() => route.query.network, value => { if (typeof value === 'string' && value !== selected.value) choose(value) })
function reset() { savedDhcp.clear(); choose('all'); tab.value = 'devices' }
function prepareRate() { const d = opened.value; if (!d || !engineReady(d.network)) return; plan.value = { kind: 'rate', network: d.network, device: d, rate: rate.value, title: '确认设备限速', change: `${d.name} · 下载 ${rate.value} Mbps`, impact: '1 台设备；仅当前网络生效' } }
function prepareDhcp() { if (!current.value?.localDhcp) return; plan.value = { kind: 'dhcp', network: current.value.id, title: '确认 DHCP 地址池修改', change: `${poolStart.value} – ${poolEnd.value} · ${lease.value}`, impact: `${count(current.value.id)} 台设备；新租约使用更新后的地址池` } }
function applyPlan() { const p = plan.value; if (!p) return; if (p.device) p.device.policy = `限速 ${p.rate} Mbps`; else savedDhcp.set(p.network, { start: poolStart.value, end: poolEnd.value, lease: lease.value }); feedback.value = `演示已应用：${networkName(p.network)}（${p.network}）· ${p.change}`; plan.value = undefined; opened.value = undefined }
</script>

<style scoped>
